perm={0: 2, 2: 3, 3: 0, 1: 4, 4: 1}
f=['up', 'tri', '$', 'D', '+']
nxt=[None]*len(f)
for src,dst in perm.items(): nxt[dst]=f[src]
subst=None
if subst:
    for i,v in subst.items(): nxt[i]=v
opts={'A': ['$', 'tri', 'D', 'up', '+'], 'B': ['D', '+', 'up', '$', 'tri'], 'C': ['$', 'tri', 'D', '+', 'up'], 'D': ['D', '$', 'up', '+', 'tri']}
assert nxt==opts['B']
for k in opts:
    if k!='B': assert nxt!=opts[k]

